 const raw=h.parse(Buffer.from(realExtraCbAccount)),ctx=require('../pumpswap-analysis-adapter-v2.cjs').context(raw),f=reducer.fees(raw,ctx,ctx.keys[0]);
 assert.equal(raw.transaction.signatures[0],extraCbAccountProvenance.signature);
