test('shared-pool global proof charges actual payer once and keeps canonical per-trader legs',()=>{
 const r=reduce(realTwoTrader);assert.equal(r.feeExpenseAttribution.chargedActions,1);
 assert.equal(r.actions.reduce((n,a)=>n+(a.fees.traderCost==='UNKNOWN'?0n:BigInt(a.fees.traderCost)),0n),BigInt(r.transactionFees.total));
 assert.equal(new Set(r.actions.map(a=>a.signature+':'+a.trader)).size,2);
 assert.deepEqual(r.actions.flatMap(a=>a.legs.map(l=>l.identity.instructionAddress.join('.'))).sort(),['10','6']);
 assert.ok(r.actions.every(a=>a.transfers.every(t=>a.legs.some(l=>h.canonical(l.identity)===h.canonical(t.associatedInvocation)))));
});
